+    for (int k = 1; k < CUDA_CPY_FUSE_MAX; ++k) {
+        if (ky == k) { cx = p.cx[k]; cdst = p.cdst[k]; }
+    }
+
+    const float * s = (const float *) (cx   + row*src_row_stride);
+    float *       d = (float *)       (cdst + row*dst_row_stride);
+
+    ggml_cuda_pdl_sync();
+    if constexpr (NE0 > 0) {
+#pragma unroll
+        for (int c = 0; c < NE0; ++c) {
+            d[c] = s[c];
+        }
+    } else {
+        for (int c = 0; c < ne0_rt; ++c) {
+            d[c] = s[c];
+        }
