+
+    const dim3 g1(nb, nrows, 1);
+    const dim3 g2(1,  nrows, 1);
+
+#define CUDA_TOP_K_LAUNCH1(E)                                                                    \
+    case E: k_top_k_stage1<E><<<g1, CUDA_TOP_K_BLOCK, 0, stream>>>(                              \
+                src, cand_alloc.get(), ncols, k); break
