+        case GGML_UNARY_OP_SIGMOID:
+            ggml_cuda_op_fused_add_unary_mul_impl<op_sigmoid>(ctx, add_node, unary_node, mul_node);
+            return true;
+        default:
+            return false;
+    }
+}
